-- Current homepage category navigation: https://www.behicesaglam.com/ (2026-11-10).
-- Adds hierarchy without deleting products or replacing category IDs. Existing
-- unkeyed categories with matching names/legacy plural names are adopted.
ALTER TABLE "Category" ADD COLUMN "slug" TEXT, ADD COLUMN "parentId" INTEGER, ADD COLUMN "sortOrder" INTEGER NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE INDEX "Category_parentId_sortOrder_idx" ON "Category"("parentId", "sortOrder");
ALTER TABLE "Category" ADD CONSTRAINT "Category_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

