ntSlug": "alt-giyim/etek", "name": "Mini etek", "sortOrder": 10, "sourceUrl": "https://www.behicesaglam.com/mini-etek", "aliases": ["Mini etek"]}, {"slug": "dis-giyim", "parentSlug": null, "name": "Dış Giyim", "sortOrder": 2, "sourceUrl": "https://www.behicesaglam.com/kadin-dis-giyim-modelleri", "aliases": ["Dış Giyim"]}, {"slug": "dis-giyim/ceket", "parentSlug": "dis-giyim", "name": "Ceket", "sortOrder": 0, "sourceUrl": "https://www.behicesaglam.com/kadin-spor-ceket-modelleri", "aliases": ["Ceket", "Ceketler"]}, {"slug": "dis-giyim/ceket/denim", "parentSlug": "dis-giyim/ceket", "name": "DENİM", "sortOrder": 0, "sourceUrl": "https://www.behicesaglam.com/kadin-spor-denim-ceket-modelleri", "aliases": ["DENİM"]}, {"slug": "dis-giyim/ceket/deri", "parentSlug": "dis-giyim/ceket", "name": "DERİ", "sortOrder": 1, "sourceUrl": "https://www.behicesaglam.com/kadin-spor-deri-ceket-modelleri", "aliases": ["DERİ"]}, {"slug": "dis-giyim/ceket/blazer", "parentSlug": "dis-giyim/ceket", "name": "BLAZER", "sortOrder": 2, "sourceUrl": "https://www.behicesaglam.com/kadin-spor-blazer-ceket-modelleri", "aliases": ["BLAZER"]}, {"slug": "dis-giyim/mont", "parentSlug": "dis-giyim", "name": "Mont", "sortOrder": 1, "sourceUrl": "https://www.behicesaglam.com/kadin-mont-modelleri", "aliases": ["Mont"]}, {"slug": "dis-giyim/mont/deri", "parentSlug": "dis-giyim/mont", "name": "DERİ", "sortOrder": 0, "sourceUrl": "https://www.behicesaglam.com/deri", "aliases": ["DERİ"]}, {"slug": "dis-giyim/mont/mevsimlik-mont", "parentSlug": "dis-giyim/mont", "name": "Mevsimlik Mont", "sortOrder": 1, "sourceUrl": "https://www.behicesaglam.com/mevsimlik-mont", "aliases": ["Mevsimlik Mont"]}, {"slug": "dis-giyim/kaban", "parentSlug": "dis-giyim", "name": "Kaban", "sortOrder": 2, "sourceUrl": "https://www.behicesaglam.com/kadin-kaban-modelleri", "aliases": ["Kaban"]}, {"slug": "dis-giyim/hirka", "parentSlug": "dis-giyim", "name": "Hırka", "sortOrder": 3, "sourceUrl": "https://www.behicesaglam.com/kadin-hirka-modelleri", "aliases": ["Hırka"]}, {"slug": "dis-giyim/hirka/triko-hirka", "parentSlug": "dis-giyim/hirka", "name": "Triko Hırka", "sortOrder": 0, "sourceUrl": "https://www.behicesaglam.com/triko-hirka", "aliases": ["Triko Hırka"]}, {"slug": "dis-giyim/trenc", "parentSlug": "dis-giyim", "name": "Trenç", "sortOrder": 4, "sourceUrl": "https://www.behicesaglam.com/trenc", "aliases": ["Trenç"]}, {"slug": "dis-giyim/yelek", "parentSlug": "dis-giyim", "name": "Yelek", "sortOrder": 5, "sourceUrl": "https://www.behicesaglam.com/yelek-1331", "aliases": ["Yelek"]}, {"slug": "aksesuar", "parentSlug": null, "name": "Aksesuar", "sortOrder": 3, "sourceUrl": "https://www.behicesaglam.com/kadin-aksesuar-modelleri", "aliases": ["Aksesuar"]}, {"slug": "aksesuar/kemer", "parentSlug": "aksesuar", "name": "Kemer", "sortOrder": 0, "sourceUrl": "https://www.behicesaglam.com/kadin-kemer-aksesuar-modelleri", "aliases": ["Kemer"]}, {"slug": "aksesuar/sal", "parentSlug": "aksesuar", "name": "Şal", "sortOrder": 1, "sourceUrl": "https://www.behicesaglam.com/sal", "aliases": ["Şal"]}, {"slug": "aksesuar/bere", "parentSlug": "aksesuar", "name": "Bere", "sortOrder": 2, "sourceUrl": "https://www.behicesaglam.com/bere", "aliases": ["Bere"]}, {"slug": "aksesuar/kolye", "parentSlug": "aksesuar", "name": "Kolye", "sortOrder": 3, "sourceUrl": "https://www.behicesaglam.com/kolye", "aliases": ["Kolye"]}, {"slug": "takim", "parentSlug": null, "name": "Takım", "sortOrder": 4, "sourceUrl": "https://www.behicesaglam.com/takim-1217", "aliases": ["Takım", "Takımlar"]}, {"slug": "takim/takim", "parentSlug": "takim", "name": "Takım", "sortOrder": 0, "sourceUrl": "https://www.behicesaglam.com/takim-3726", "aliases": ["Takım", "Takımlar"]}, {"slug": "takim/takim/blazer", "parentSlug": "takim/takim", "name": "BLAZER", "sortOrder": 0, "sourceUrl": "https://www.behicesaglam.com/blazer-1190", "aliases": ["BLAZER"]}, {"slug": "500tl", "parentSlug": null, "name": "500TL", "sortOrder": 5, "sourceUrl": "https://www.behicesaglam.com/500tl", "aliases": ["500TL"]}]$data$::jsonb)
  LOOP
    parent_id := NULL;
    IF node->>'parentSlug' IS NOT NULL THEN
      SELECT "id" INTO parent_id FROM "Category" WHERE "slug" = node->>'parentSlug';
      IF parent_id IS NULL THEN RAISE EXCEPTION 'Missing taxonomy parent'; END IF;
    END IF;
    SELECT "id" INTO existing_id FROM "Category" WHERE "slug" = node->>'slug';
    IF existing_id IS NULL THEN
      SELECT "id" INTO existing_id FROM "Category"
      WHERE "slug" IS NULL
        AND ("parentId" IS NOT DISTINCT FROM parent_id OR "parentId" IS NULL)
        AND "name" IN (SELECT jsonb_array_elements_text(node->'aliases'))
      ORDER BY "id" LIMIT 1;
      IF existing_id IS NULL THEN
        INSERT INTO "Category" ("name", "slug", "parentId", "sortOrder")
        VALUES (node->>'name', node->>'slug', parent_id, (node->>'sortOrder')::integer);
      ELSE
        UPDATE "Category" SET "name"=node->>'name', "slug"=node->>'slug', "parentId"=parent_id, "sortOrder"=(node->>'sortOrder')::integer WHERE "id"=existing_id;
      END IF;
    END IF;
  END LOOP;
END $taxonomy$;
